#include <psre/m043/process.h>
#include <psre/m006/fs.h>
#include <psre/serial.h>
#include <stddef.h>
static psre_m043_status_t st;
static void cp(char*d,const char*s,uint32_t n){uint32_t i=0;if(!d||!n)return;while(s&&s[i]&&i+1<n){d[i]=s[i];++i;}d[i]=0;}
static void history_save(bool ok){psre_m043_history_t*h=&st.history[st.history_next];*h=(psre_m043_history_t){.id=st.job_id,.job=st.job,.result=ok?PSRE_M043_COMPLETED:PSRE_M043_FAILED,.success=ok,.bytes_done=st.bytes_done,.bytes_total=st.bytes_total,.attempts=st.retries+1u};cp(h->path,st.path,sizeof(h->path));st.history_next=(uint8_t)((st.history_next+1u)%PSRE_M043_HISTORY_CAPACITY);if(st.history_count<PSRE_M043_HISTORY_CAPACITY)++st.history_count;}
static bool begin(psre_m043_job_t job,const char*path){if(!st.initialized||st.state==PSRE_M043_RUNNING||st.state==PSRE_M043_PAUSED)return false;++st.job_id;st.job=job;st.state=PSRE_M043_RUNNING;st.files_done=0;st.files_total=1;st.bytes_done=st.bytes_total=0;st.steps=0;st.retries=0;st.errors=0;cp(st.path,path?path:"",sizeof(st.path));return true;}
bool psre_m043_initialize(psre_m038_container_id_t c){(void)c;if(st.initialized)return true;st.initialized=true;st.state=PSRE_M043_IDLE;st.job=PSRE_M043_JOB_NONE;serial_write("[M043] Recovery Process Manager initialized.\n");return true;}
bool psre_m043_start_stage(const char*p){if(!st.initialized)(void)psre_m043_initialize(PSRE_M038_INVALID_CONTAINER);if(!p||!*p||!begin(PSRE_M043_JOB_STAGE_FILE,p))return false;return true;}
bool psre_m043_start_queue_export(void){if(!st.initialized)(void)psre_m043_initialize(PSRE_M038_INVALID_CONTAINER);uint32_t count=0,bytes=0;if(!psre_m009_queue_get_info(&count,&bytes)||!count||!begin(PSRE_M043_JOB_EXPORT_QUEUE,0))return false;psre_m009_queue_manifest();if(!psre_m009_export_begin()){st.state=PSRE_M043_FAILED;++st.errors;history_save(false);return false;}st.files_total=count;st.bytes_total=bytes;return true;}
bool psre_m043_pause(void){if(st.state!=PSRE_M043_RUNNING)return false;st.state=PSRE_M043_PAUSED;serial_write("[M043] Job paused.\n");return true;}
bool psre_m043_resume(void){if(st.state!=PSRE_M043_PAUSED)return false;st.state=PSRE_M043_RUNNING;serial_write("[M043] Job resumed.\n");return true;}
bool psre_m043_retry(void){if(st.state!=PSRE_M043_FAILED)return false;++st.retries;st.state=PSRE_M043_RUNNING;if(st.job==PSRE_M043_JOB_STAGE_FILE)return true;if(st.job==PSRE_M043_JOB_EXPORT_QUEUE){psre_m009_queue_manifest();if(psre_m009_export_begin())return true;}st.state=PSRE_M043_FAILED;++st.errors;return false;}
void psre_m043_tick(void){if(st.state!=PSRE_M043_RUNNING)return;++st.steps;if(st.job==PSRE_M043_JOB_STAGE_FILE){bool ok=psre_m008_recover(st.path);if(ok){st.state=PSRE_M043_COMPLETED;st.files_done=1;st.bytes_done=st.bytes_total=0;history_save(true);}else{st.state=PSRE_M043_FAILED;++st.errors;history_save(false);}return;}if(st.job==PSRE_M043_JOB_EXPORT_QUEUE){bool done=false;uint32_t b=0,t=0,f=0;if(!psre_m009_export_step(256u,&b,&t,&f,&done)){st.state=PSRE_M043_FAILED;++st.errors;history_save(false);return;}st.bytes_done=b;st.bytes_total=t;st.files_done=f;if(done){st.state=PSRE_M043_COMPLETED;st.files_done=st.files_total;history_save(true);}}}
void psre_m043_cancel(void){if(st.job==PSRE_M043_JOB_EXPORT_QUEUE)psre_m009_export_cancel();if(st.state==PSRE_M043_RUNNING||st.state==PSRE_M043_PAUSED){st.state=PSRE_M043_FAILED;++st.errors;history_save(false);}}
const psre_m043_status_t*psre_m043_get_status(void){return &st;}
static void num(uint32_t v){char b[11];uint32_t n=0;do{b[n++]=(char)('0'+v%10u);v/=10u;}while(v&&n<10u);while(n)serial_write_char(b[--n]);}
void psre_m043_report(void){static const char*names[]={"IDLE","RUNNING","PAUSED","COMPLETED","FAILED"};serial_write("[M043] state=");serial_write(names[(unsigned)st.state<=PSRE_M043_FAILED?st.state:PSRE_M043_FAILED]);serial_write(" job_id=");num(st.job_id);serial_write(" progress=");num(st.bytes_done);serial_write("/");num(st.bytes_total);serial_write(" steps=");num(st.steps);serial_write(" history=");num(st.history_count);serial_write(" errors=");num(st.errors);serial_write("\n");for(uint32_t i=0;i<st.history_count;i++){uint32_t ix=(st.history_next+PSRE_M043_HISTORY_CAPACITY-st.history_count+i)%PSRE_M043_HISTORY_CAPACITY;const psre_m043_history_t*h=&st.history[ix];serial_write("  job ");num(h->id);serial_write(" result=");serial_write(h->success?"OK":"FAILED");serial_write(" bytes=");num(h->bytes_done);serial_write("/");num(h->bytes_total);if(h->path[0]){serial_write(" path=");serial_write(h->path);}serial_write(" attempts=");num(h->attempts);serial_write("\n");}}
